REQUIRED = {"claim_id", "evidence_id", "resolves", "support", "action"}
ALLOWED_RESOLVES = {"YES", "NO", "PARTIAL"}
ALLOWED_SUPPORT = {"DIRECT", "PARTIAL", "BACKGROUND", "UNSUPPORTED", "CONTRADICTS"}
ALLOWED_ACTIONS = {"KEEP", "REPLACE", "QUALIFY", "REMOVE"}
_UNSET = object()


def _materialize_expected_ids(expected_claim_ids):
    if expected_claim_ids is None:
        return ["expected_claim_ids: expected iterable of nonempty strings"], None
    if isinstance(expected_claim_ids, (str, bytes, dict)):
        return ["expected_claim_ids: expected iterable of nonempty strings"], None
    try:
        values = list(expected_claim_ids)
    except TypeError:
        return ["expected_claim_ids: expected iterable of nonempty strings"], None
    if any(not isinstance(value, str) or not value.strip() for value in values):
        return ["expected_claim_ids: elements must be nonempty strings"], None
    return [], values


def check(records, expected_claim_ids=_UNSET):
    if not isinstance(records, list):
        return ["records: expected list"]

    errors = []
    seen = set()

    for number, record in enumerate(records, 1):
        if not isinstance(record, dict):
            errors.append(f"row {number}: expected object")
            continue

        missing = sorted(REQUIRED - set(record))
        if missing:
            errors.append(f"row {number}: missing fields {missing}")

        for field in ("claim_id", "evidence_id"):
            if field in record and (
                not isinstance(record[field], str) or not record[field].strip()
            ):
                errors.append(f"row {number}: {field} must be nonempty string")

        claim_id = record.get("claim_id")
        if isinstance(claim_id, str) and claim_id.strip():
            if claim_id in seen:
                errors.append(f"row {number}: duplicate claim_id {claim_id}")
            seen.add(claim_id)

        resolves = record.get("resolves")
        if "resolves" in record and (
            not isinstance(resolves, str) or resolves not in ALLOWED_RESOLVES
        ):
            errors.append(f"row {number}: invalid resolves value")

        support = record.get("support")
        if "support" in record and (
            not isinstance(support, str) or support not in ALLOWED_SUPPORT
        ):
            errors.append(f"row {number}: invalid support category")

        action = record.get("action")
        if "action" in record and (
            not isinstance(action, str) or action not in ALLOWED_ACTIONS
        ):
            errors.append(f"row {number}: invalid action")

    if expected_claim_ids is not _UNSET:
        expected_errors, expected_values = _materialize_expected_ids(
            expected_claim_ids
        )
        if expected_errors:
            errors.extend(expected_errors)
        else:
            expected = set(expected_values)
            missing_expected = sorted(expected - seen)
            unexpected = sorted(seen - expected)
            if missing_expected:
                errors.append(f"missing claim_ids: {missing_expected}")
            if unexpected:
                errors.append(f"unexpected claim_ids: {unexpected}")

    return errors


valid = [
    {"claim_id": "C-201", "evidence_id": "E-201", "resolves": "YES", "support": "DIRECT", "action": "KEEP"},
    {"claim_id": "C-202", "evidence_id": "E-201", "resolves": "YES", "support": "PARTIAL", "action": "QUALIFY"},
    {"claim_id": "C-203", "evidence_id": "E-203", "resolves": "YES", "support": "UNSUPPORTED", "action": "REMOVE"}
]
expected = ["C-201", "C-202", "C-203"]

worked = [
    {"claim_id": "TASK-42-C1", "evidence_id": "E-PY-1", "resolves": "YES", "support": "DIRECT", "action": "KEEP"},
    {"claim_id": "TASK-42-C2", "evidence_id": "E-PY-1", "resolves": "PARTIAL", "support": "PARTIAL", "action": "QUALIFY"}
]
worked_expected = {"TASK-42-C1", "TASK-42-C2"}
changed_input = [
    {"claim_id": "TASK-42-C2-CHANGED", "evidence_id": "E-PY-1", "resolves": "PARTIAL", "support": "PARTIAL", "action": "REPLACE"}
]
changed_expected = ("TASK-42-C2-CHANGED",)

duplicate = [
    valid[0],
    {"claim_id": "C-201", "evidence_id": "E-204", "resolves": "YES", "support": "BACKGROUND", "action": "KEEP"}
]
unexpected = [
    {"claim_id": "C-999", "evidence_id": "E-999", "resolves": "NO", "support": "UNSUPPORTED", "action": "REMOVE"}
]
list_id = [
    {"claim_id": ["C-201"], "evidence_id": "E-201", "resolves": "YES", "support": "DIRECT", "action": "KEEP"}
]
missing_fields = [{"claim_id": "C-201"}]
invalid_enum = [
    {"claim_id": "C-201", "evidence_id": "E-201", "resolves": "MAYBE", "support": "LIKELY", "action": "PUBLISH"}
]
enum_shapes = [
    {"claim_id": "C-201", "evidence_id": "E-201", "resolves": ["YES"], "support": {"kind": "DIRECT"}, "action": None}
]

cases = [
    ("valid fixture", valid, expected, []),
    ("evidence reuse fixture", valid, expected, []),
    ("worked case fixture", worked, worked_expected, []),
    ("changed input fixture", changed_input, changed_expected, []),
    ("generator expected IDs fixture", valid, (value for value in expected), []),
    ("iterator expected IDs fixture", valid, iter(expected), []),
    ("duplicate claim fixture", duplicate, ["C-201"], ["row 2: duplicate claim_id C-201"]),
    ("empty coverage fixture", [], expected, ["missing claim_ids: ['C-201', 'C-202', 'C-203']"]),
    ("unexpected coverage fixture", unexpected, ["C-201"], ["missing claim_ids: ['C-201']", "unexpected claim_ids: ['C-999']"]),
    ("malformed top fixture", "not a list", _UNSET, ["records: expected list"]),
    ("malformed row fixture", [42], _UNSET, ["row 1: expected object"]),
    ("list ID fixture", list_id, _UNSET, ["row 1: claim_id must be nonempty string"]),
    ("missing fields fixture", missing_fields, _UNSET, ["row 1: missing fields ['action', 'evidence_id', 'resolves', 'support']"]),
    ("invalid enum fixture", invalid_enum, _UNSET, ["row 1: invalid resolves value", "row 1: invalid support category", "row 1: invalid action"]),
    ("enum shape fixture", enum_shapes, _UNSET, ["row 1: invalid resolves value", "row 1: invalid support category", "row 1: invalid action"]),
    ("null expected IDs fixture", valid, None, ["expected_claim_ids: expected iterable of nonempty strings"]),
    ("dict expected IDs fixture", valid, {"C-201": True}, ["expected_claim_ids: expected iterable of nonempty strings"]),
    ("bare string expected IDs fixture", valid, "C-201", ["expected_claim_ids: expected iterable of nonempty strings"]),
    ("list-valued expected IDs fixture", valid, [{"claim_id": "C-201"}], ["expected_claim_ids: elements must be nonempty strings"]),
    ("generator element fixture", valid, (value for value in ["C-201", 42]), ["expected_claim_ids: elements must be nonempty strings"]),
    ("non-iterable expected IDs fixture", valid, 42, ["expected_claim_ids: expected iterable of nonempty strings"])
]

