rendered_lines = []
for label, records, coverage, expected_errors in cases:
    actual = check(records, coverage)
    assert actual == expected_errors, (label, actual, expected_errors)
    rendered_lines.append(f"{label}: {actual}")

rendered_stdout = "\n".join(rendered_lines)
assert rendered_stdout == EXPECTED_STDOUT, (rendered_stdout, EXPECTED_STDOUT)
